<body>
  <header class="topbar">
    <div class="brand">
      <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/004.png" width="47" height="56" alt="Missing Dice logo">
      <a class="btn" href="#">Missing Dice</a>
    </div>
    <div class="right-nav">
      <a class="coffee btn" href="#">Buy me a coffee</a>
      <button class="mode btn" type="button">
        <span>Color modes</span>
        <span class="mode-arrow">⌄</span>
      </button>
    </div>
  </header>

  <main>
    <section class="intro">
      <h1>Roll a D8</h1>
      <p>Use this too to roll any amount of <b>8-sided dice.</b></p>
      <p>For more options try our <a class="btn" href="#">all-purpose dice roller.</a></p>
    </section>

    <section class="controls">
      <div class="counter-box">
        <span class="counter-label">number of 8-sided dice:</span>
        <div class="counter">
          <button class="btn minus" type="button">-</button>
          <input id="amount" type="text" value="1" readonly aria-label="Number of dice">
          <button class="btn plus" type="button">+</button>
        </div>
      </div>
    </section>

    <section id="diceArea" class="dice-area">
      <div class="die single-die">
        <span class="die-number">7</span>
      </div>
    </section>

    <section class="total-area">
      <div class="total">TOTAL:<strong id="totalValue">7</strong></div>
    </section>

    <section class="roll-area">
      <button id="roll" class="roll btn" type="button">ROLL DICE</button>
    </section>
  </main>

<script>
  const amountInput = document.getElementById('amount');
  const diceArea = document.getElementById('diceArea');
  const totalValue = document.getElementById('totalValue');
  const plus = document.querySelector('.plus');
  const minus = document.querySelector('.minus');
  const rollButton = document.getElementById('roll');

  let amount = 1;
  let rollIndex = 0;

  const rollSets = [
    [1, 5, 5, 1],
    [2, 1, 8, 3],
    [1, 7, 8, 6]
  ];

  function setAmount(value) {
    amount = Math.max(1, Math.min(20, value));
    amountInput.value = amount;
  }

  function makeDie(value) {
    const die = document.createElement('div');
    die.className = 'die';
    const number = document.createElement('span');
    number.className = 'die-number';
    number.textContent = value;
    die.appendChild(number);
    return die;
  }

  function render(values) {
    diceArea.innerHTML = '';
    values.forEach(value => diceArea.appendChild(makeDie(value)));
    totalValue.textContent = values.reduce((a, b) => a + b, 0);
  }

  plus.addEventListener('click', () => setAmount(amount + 1));
  minus.addEventListener('click', () => setAmount(amount - 1));

  rollButton.addEventListener('click', () => {
    let values;
    if (amount === 1 && rollIndex === 0) {
      values = [7];
    } else {
      const source = rollSets[Math.min(rollIndex, rollSets.length - 1)];
      values = [];
      for (let i = 0; i < amount; i++) {
        values.push(source[i % source.length]);
      }
    }
    render(values);
    if (amount > 1 || rollIndex > 0) rollIndex++;
  });
</script>
